import{_ as r,o as t,c as e,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS Hammer (Day 2) - OSD: Scrub and Repair","description":"","frontmatter":{"title":"CDS Hammer (Day 2) - OSD: Scrub and Repair","date":"2014-10-30T00:00:00.000Z","updated":"2014-10-30T00:00:00.000Z","tags":["Ceph","OSD","Scrub and Repair","存储修复","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_2_-_OSD_-_Scrub_and_Repair.md","filePath":"posts/2014/CDS_Hammer_Day_2_-_OSD_-_Scrub_and_Repair.md","lastUpdated":1780459816000}'),l={name:"posts/2014/CDS_Hammer_Day_2_-_OSD_-_Scrub_and_Repair.md"};function _(o,a,s,n,p,S){return t(),e("div",null,[...a[0]||(a[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： 讨论并优化 Ceph 分布式存储系统中 OSD（Object Storage Daemon）的扫描和修复方案</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Samuel, Guang, Jason, 以及其他相关人员</p><p><strong>会议内容</strong>：</p><ul><li><strong>主要议题</strong>： 讨论如何提高 OSD 扫描和修复的效率和准确性，以解决当前扫描方案不够智能和保守的问题。</li><li><strong>关键细节</strong>： <ul><li>针对当前扫描修复方案，提出改进措施，使其能够更有效地识别和修复损坏的副本。</li><li>讨论使用 Calamari 或其他工具向用户展示不一致性细节，并允许用户指定修复方式。</li><li>探讨通过 Liberator 接口或 JSON 接口暴露相关信息，以便用户查询和操作。</li><li>讨论异步读取在复制副本中的实现，以及如何将异步读取应用于对象存储接口。</li><li>讨论读取原始数据分片的需求，以及如何通过新的接口实现。</li></ul></li><li><strong>决定事项</strong>： <ul><li>将扫描结果存储在 Perftest scratch 对象中，并在对等重置期间清除。</li><li>通过 Liberator 接口提供查询不一致副本和修复对象的命令。</li><li>实现异步读取并应用于对象存储接口。</li><li>提供读取原始数据分片的接口。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>Guang 将提交一个关于将保守第一步改为将 EIO 读取等同于 scrub 获取 I/O 并标记 pg 不一致的 pull request。</li><li>实现异步读取并应用于复制副本。</li><li>实现读取原始数据分片的接口。</li><li>开发一个工具，帮助用户查询和操作不一致副本和修复对象。</li></ul></li></ul><p><strong>关键词</strong>： Ceph, OSD, 扫描修复, Liberator, JSON, 异步读取, 数据分片, Calamari, Perftest, Liberator 接口, JSON 接口</p>',7)])])}const d=r(l,[["render",_]]);export{c as __pageData,d as default};
